1	package release
2	
3	import (
4		"encoding/json"
5		"fmt"
6		"time"
7	)
8	
9	const (
10		opCreateBatch = "createBatch"
11		opUpdateDraft = "updateDraftBatch"
12		opStartBatch  = "startBatch"
13		opCloseBatch  = "closeBatch"
14		opAddFeeding  = "addFeeding"
15	)
16	
17	type createBatchPayload struct {
18		BatchNo  string
19		RecipeNo string
20		Version  string
21		Portions int
22	}
23	
24	type updateDraftPayload struct {
25		BatchNo  string
26		RecipeNo string // 留空表示不改配方
27		Version  string // 与 RecipeNo 同时给出
28		Portions int    // 0 表示不改份数
29	}
30	
31	type startBatchPayload struct {
32		BatchNo string
33	}
34	
35	type closeBatchPayload struct {
36		BatchNo string
37	}
38	
39	type addFeedingPayload struct {
40		BatchNo    string
41		MaterialNo string
42		Grams      string
43		Time       time.Time
44		Registrar  string
45	}
46	
47	// CreateBatch 创建批次。
48	// 批次使用独立批次编号，选择已登记的配方版本和计划份数（必须为正整数）。
49	// 新批次为草稿；批次编号重复、配方版本不存在或数量不合法时返回具体原因且不保留数据。
50	func (s *Store) CreateBatch(reqNo, batchNo, recipeNo, version string, portions int) (*BatchView, error) {
51		payload := createBatchPayload{BatchNo: batchNo, RecipeNo: recipeNo, Version: version, Portions: portions}
52		var out BatchView
53		err := s.write(reqNo, opCreateBatch, payload, func(st *persistedState) (json.RawMessage, error) {
54			if batchNo == "" {
55				return nil, fmt.Errorf("%w: 批次编号不能为空", ErrInvalidInput)
56			}
57			if portions <= 0 {
58				return nil, fmt.Errorf("%w: 计划份数必须为正整数，得到 %d", ErrInvalidInput, portions)
59			}
60			if findBatch(st, batchNo) != nil {
61				return nil, fmt.Errorf("%w: 批次 %q 已存在", ErrDuplicateBatch, batchNo)
62			}
63			r := findRecipe(st, recipeNo, version)
64			if r == nil {
65				return nil, fmt.Errorf("%w: 配方 %q 版本 %q 不存在", ErrNotFound, recipeNo, version)
66			}
67			// 份数为正整数还要满足：按该配方版本逐物料计算的应投量都能精确
68			// 表示且不超上限。这是本次提交的输入规则，不满足按 ErrInvalidInput
69			// 拒绝，不能落盘成之后读取时才发现损坏的批次。
70			if err := validatePlanForRecipe(r, portions); err != nil {
71				return nil, fmt.Errorf("%w: %v", ErrInvalidInput, err)
72			}
73			b := &batchRecord{
74				BatchNo:         batchNo,
75				RecipeNo:        recipeNo,
76				RecipeVersion:   version,
77				PlannedPortions: portions,
78				Status:          StatusDraft,
79			}
80			view, err := buildBatchView(b, r)
81			if err != nil {
82				return nil, err
83			}
84			raw, err := json.Marshal(view)
85			if err != nil {
86				return nil, err
87			}
88			st.Batches = append(st.Batches, b)
89			return raw, nil
90		}, &out)
91		if err != nil {
92			return nil, err
93		}
94		return &out, nil
95	}
96	
97	// UpdateDraftBatch 调整草稿批次的计划份数或改选配方版本。
98	// newRecipeNo/newVersion 都留空表示不改配方；newPortions 传 0 表示不改份数。
99	// 只有草稿状态可以调整；开始执行后两者固定。
100	func (s *Store) UpdateDraftBatch(reqNo, batchNo, newRecipeNo, newVersion string, newPortions int) (*BatchView, error) {
101		payload := updateDraftPayload{BatchNo: batchNo, RecipeNo: newRecipeNo, Version: newVersion, Portions: newPortions}
102		var out BatchView
103		err := s.write(reqNo, opUpdateDraft, payload, func(st *persistedState) (json.RawMessage, error) {
104			b := findBatch(st, batchNo)
105			if b == nil {
106				return nil, fmt.Errorf("%w: 批次 %q", ErrNotFound, batchNo)
107			}
108			if b.Status != StatusDraft {
109				return nil, fmt.Errorf("%w: 批次 %q 状态为 %s，只有草稿可以调整", ErrInvalidState, batchNo, b.Status)
110			}
111			// 先解析调整后的最终份数与配方版本（份数传 0 表示沿用原份数，
112			// 配方编号与版本号都留空表示沿用原版本），全部解析并校验通过
113			// 后才改动记录，保证失败时不留下半调整状态。
114			finalPortions := b.PlannedPortions
115			if newPortions != 0 {
116				if newPortions <= 0 {
117					return nil, fmt.Errorf("%w: 计划份数必须为正整数，得到 %d", ErrInvalidInput, newPortions)
118				}
119				finalPortions = newPortions
120			}
121			finalRecipeNo, finalVersion := b.RecipeNo, b.RecipeVersion
122			if newRecipeNo != "" || newVersion != "" {
123				if newRecipeNo == "" || newVersion == "" {
124					return nil, fmt.Errorf("%w: 改选配方版本时必须同时给出配方编号和版本号", ErrInvalidInput)
125				}
126				finalRecipeNo, finalVersion = newRecipeNo, newVersion
127			}
128			r := findRecipe(st, finalRecipeNo, finalVersion)
129			if r == nil {
130				return nil, fmt.Errorf("%w: 配方 %q 版本 %q 不存在", ErrNotFound, finalRecipeNo, finalVersion)
131			}
132			// 最终计划同样必须满足：每种物料按最终版本、最终份数计算的应投量
133			// 都能精确表示且不超上限；沿用合法原计划（无变化调整）时该校验
134			// 在读取时已经通过，这里再统一校验一次。这是本次提交的输入规则，
135			// 不满足按 ErrInvalidInput 整体拒绝，不落盘份数或配方的半成品。
136			if err := validatePlanForRecipe(r, finalPortions); err != nil {
137				return nil, fmt.Errorf("%w: %v", ErrInvalidInput, err)
138			}
139			b.PlannedPortions = finalPortions
140			b.RecipeNo = finalRecipeNo
141			b.RecipeVersion = finalVersion
142			view, err := buildBatchView(b, r)
143			if err != nil {
144				return nil, err
145			}
146			raw, err := json.Marshal(view)
147			if err != nil {
148				return nil, err
149			}
150			return raw, nil
151		}, &out)
152		if err != nil {
153			return nil, err
154		}
155		return &out, nil
156	}
157	
158	// StartBatch 开始执行批次：草稿 → 执行中。
159	// 开始后计划份数与配方版本固定，只有执行中的批次可以关闭。
160	func (s *Store) StartBatch(reqNo, batchNo string) (*BatchView, error) {
161		payload := startBatchPayload{BatchNo: batchNo}
162		var out BatchView
163		err := s.write(reqNo, opStartBatch, payload, func(st *persistedState) (json.RawMessage, error) {
164			b := findBatch(st, batchNo)
165			if b == nil {
166				return nil, fmt.Errorf("%w: 批次 %q", ErrNotFound, batchNo)
167			}
168			if b.Status != StatusDraft {
169				return nil, fmt.Errorf("%w: 批次 %q 状态为 %s，只有草稿可以开始执行", ErrInvalidState, batchNo, b.Status)
170			}
171			b.Status = StatusExecuting
172			r := findRecipe(st, b.RecipeNo, b.RecipeVersion)
173			if r == nil {
174				return nil, fmt.Errorf("%w: 批次 %q 绑定的配方 %q 版本 %q 未登记",
175					ErrCorruptData, b.BatchNo, b.RecipeNo, b.RecipeVersion)
176			}
177			view, err := buildBatchView(b, r)
178			if err != nil {
179				return nil, err
180			}
181			raw, err := json.Marshal(view)
182			if err != nil {
183				return nil, err
184			}
185			return raw, nil
186		}, &out)
187		if err != nil {
188			return nil, err
189		}
190		return &out, nil
191	}
192	
193	// CloseBatch 关闭批次：执行中 → 已关闭。
194	// 关闭表示确认已有投料，不要求数量已经吻合；
195	// 关闭后不能追加投料，也不能重新打开。
196	func (s *Store) CloseBatch(reqNo, batchNo string) (*BatchView, error) {
197		payload := closeBatchPayload{BatchNo: batchNo}
198		var out BatchView
199		err := s.write(reqNo, opCloseBatch, payload, func(st *persistedState) (json.RawMessage, error) {
200			b := findBatch(st, batchNo)
201			if b == nil {
202				return nil, fmt.Errorf("%w: 批次 %q", ErrNotFound, batchNo)
203			}
204			if b.Status != StatusExecuting {
205				return nil, fmt.Errorf("%w: 批次 %q 状态为 %s，只有执行中的批次可以关闭", ErrInvalidState, batchNo, b.Status)
206			}
207			b.Status = StatusClosed
208			r := findRecipe(st, b.RecipeNo, b.RecipeVersion)
209			if r == nil {
210				return nil, fmt.Errorf("%w: 批次 %q 绑定的配方 %q 版本 %q 未登记",
211					ErrCorruptData, b.BatchNo, b.RecipeNo, b.RecipeVersion)
212			}
213			view, err := buildBatchView(b, r)
214			if err != nil {
215				return nil, err
216			}
217			raw, err := json.Marshal(view)
218			if err != nil {
219				return nil, err
220			}
221			return raw, nil
222		}, &out)
223		if err != nil {
224			return nil, err
225		}
226		return &out, nil
227	}
228	
229	// AddFeeding 向执行中的批次追加一次投料。
230	// 投料包含物料编号、克数（正数、最多三位小数）、投料时间和登记人；
231	// 物料必须属于该批次绑定的配方版本。允许实际投料不足或超过应投量；
232	// 已登记的投料不能修改或删除，关闭后也不能追加。
233	// 同一批次内每种物料的累计实投量（仅按该物料统计）上限为
234	// 9223372036854775.807 克，本次投料后恰好等于上限仍允许，超过则返回
235	// ErrInvalidInput 且不保存本次投料。
236	// 投料按成功登记的先后顺序编号，不按投料时间重排。
237	func (s *Store) AddFeeding(reqNo, batchNo, materialNo, grams string, t time.Time, registrar string) (*FeedingView, error) {
238		payload := addFeedingPayload{
239			BatchNo:    batchNo,
240			MaterialNo: materialNo,
241			Grams:      grams,
242			Time:       t,
243			Registrar:  registrar,
244		}
245		var out FeedingView
246		err := s.write(reqNo, opAddFeeding, payload, func(st *persistedState) (json.RawMessage, error) {
247			if materialNo == "" {
248				return nil, fmt.Errorf("%w: 物料编号不能为空", ErrInvalidInput)
249			}
250			if registrar == "" {
251				return nil, fmt.Errorf("%w: 登记人不能为空", ErrInvalidInput)
252			}
253			milli, err := parseGrams(grams)
254			if err != nil {
255				return nil, fmt.Errorf("%w: 物料 %q 的克数: %v", ErrInvalidInput, materialNo, err)
256			}
257			b := findBatch(st, batchNo)
258			if b == nil {
259				return nil, fmt.Errorf("%w: 批次 %q", ErrNotFound, batchNo)
260			}
261			if b.Status != StatusExecuting {
262				return nil, fmt.Errorf("%w: 批次 %q 状态为 %s，只有执行中的批次可以投料", ErrInvalidState, batchNo, b.Status)
263			}
264			r := findRecipe(st, b.RecipeNo, b.RecipeVersion)
265			if r == nil {
266				return nil, fmt.Errorf("%w: 批次 %q 绑定的配方 %q 版本 %q 未登记",
267					ErrCorruptData, b.BatchNo, b.RecipeNo, b.RecipeVersion)
268			}
269			belongs := false
270			for _, m := range r.Materials {
271				if m.MaterialNo == materialNo {
272					belongs = true
273					break
274				}
275			}
276			if !belongs {
277				return nil, fmt.Errorf("%w: 物料 %q 不在配方 %q 版本 %q 中",
278					ErrMaterialNotInRecipe, materialNo, r.RecipeNo, r.Version)
279			}
280	
281			// 上限按物料分别判断：只累计该物料已登记的投料，
282			// 其他物料的投料量不参与，也不互相抵消。
283			acc := newFeedingAccumulator()
284			fit := true
285			for _, f := range b.Feedings {
286				if !acc.add(f.MaterialNo, f.GramsMilli) {
287					fit = false
288					break
289				}
290			}
291			if !fit || !acc.add(materialNo, milli) {
292				return nil, fmt.Errorf("%w: 物料 %q 的数量超出范围：本次投料后累计实投将超过上限 %s 克",
293					ErrInvalidInput, materialNo, maxGramsMilli)
294			}
295	
296			seq := len(b.Feedings) + 1
297			rec := feedingRecord{
298				Seq:        seq,
299				MaterialNo: materialNo,
300				GramsMilli: milli,
301				Time:       t,
302				Registrar:  registrar,
303			}
304			view := FeedingView{
305				Seq:        seq,
306				MaterialNo: materialNo,
307				Grams:      milli.String(),
308				Time:       t,
309				Registrar:  registrar,
310			}
311			raw, err := json.Marshal(view)
312			if err != nil {
313				return nil, err
314			}
315			b.Feedings = append(b.Feedings, rec)
316			return raw, nil
317		}, &out)
318		if err != nil {
319			return nil, err
320		}
321		return &out, nil
322	}
323	
324	// GetBatch 按批次编号查询，返回未找到（ErrNotFound）时表示批次不存在。
325	// 返回内容包含所用配方版本、计划份数、状态、全部投料（登记顺序），
326	// 以及按物料逐项的应投量、累计实投量和差额；无投料的物料也会列出。
327	// 返回的视图是台账数据的副本，调用方修改不会影响台账。
328	func (s *Store) GetBatch(batchNo string) (*BatchView, error) {
329		var out *BatchView
330		err := s.read(func(st *persistedState) error {
331			b := findBatch(st, batchNo)
332			if b == nil {
333				return fmt.Errorf("%w: 批次 %q", ErrNotFound, batchNo)
334			}
335			r := findRecipe(st, b.RecipeNo, b.RecipeVersion)
336			if r == nil {
337				return fmt.Errorf("%w: 批次 %q 绑定的配方 %q 版本 %q 不存在",
338					ErrCorruptData, batchNo, b.RecipeNo, b.RecipeVersion)
339			}
340			view, err := buildBatchView(b, r)
341			if err != nil {
342				return err
343			}
344			out = view
345			return nil
346		})
347		if err != nil {
348			return nil, err
349		}
350		return out, nil
351	}
