1	package release
2	
3	import (
4		"encoding/json"
5		"errors"
6		"fmt"
7		"os"
8		"path/filepath"
9		"sync"
10		"syscall"
11	)
12	
13	const (
14		stateFileName = "ledger.json"
15		lockFileName  = "ledger.lock"
16		stateVersion  = 1
17	)
18	
19	// Store 是一个本地配方批次台账，数据保存在调用方指定的目录中。
20	// 不同目录互相独立；多个 Store 可以安全并发提交（进程内互斥、进程间文件锁）。
21	type Store struct {
22		// dir 是打开时确定的绝对路径。即使传入相对目录，也在 Open 时按当时的
23		// 工作目录解析并固定下来：此后调用方切换进程工作目录，本对象的读取与
24		// 保存仍指向最初打开的位置，绝不会按新工作目录重新解释这个相对路径。
25		dir      string
26		lockFile *os.File
27		mu       sync.Mutex
28		state    *persistedState
29	}
30	
31	// Open 打开（或首次使用）位于 dir 的台账。
32	// 目录不存在时会创建；目录中没有台账文件时得到空台账；
33	// 台账文件已存在但没有任何内容（零字节，无论原本就是空文件还是使用中被截断）
34	// 时按损坏处理；已有台账文件无法读取、解析，存在两条配方编号与版本号
35	// 完全相同的配方记录，存在两条批次编号完全相同的批次记录，
36	// 任一配方版本的任一物料每份克数不是正数，
37	// 任一配方版本内同一物料编号出现多次，
38	// 任一批次绑定的配方版本未登记，
39	// 任一批次的计划份数不是正整数，或按其绑定的配方版本计算时某物料的
40	// 应投量（每份克数 × 计划份数）无法精确表示到千分之一克或超过
41	// 9223372036854775.807 克，
42	// 任一批次仍为草稿状态却带有投料记录，
43	// 已保存投料的物料编号不属于该批次绑定的配方版本，
44	// 或已保存的投料数量非法（单条不是正数，或同一批次同一物料累计实投
45	// 超过 9223372036854775.807 克）时，返回 ErrCorruptData（可用 errors.Is
46	// 判断），不会当成空台账继续保存，也不会返回可继续使用的台账对象。
47	//
48	// dir 可以是相对目录：其位置只按 Open 调用时的工作目录解析一次并固定。
49	// 打开之后即使进程切换了工作目录，本对象的查询与保存仍始终指向最初打开
50	// 的目录，不会按新工作目录重新解释相对路径；台账操作本身也不会改变调用
51	// 方的工作目录。切换工作目录后另行 Open 同一相对目录，得到的是绑定新位
52	// 置的独立对象，与此前的对象互不影响。
53	func Open(dir string) (*Store, error) {
54		if dir == "" {
55			return nil, errors.New("数据位置不能为空")
56		}
57		// 先按“打开那一刻”的工作目录把位置解析成绝对路径并固定。后续每次
58		// 查询与写入都会重新读取台账文件，若仍持有相对路径，调用方一旦切换
59		// 工作目录，相对路径就会指向别处——可能把已登记批次查成不存在，或把
60		// 变更读写到另一个同名台账。解析为绝对路径后，本对象始终绑定最初打
61		// 开的位置。filepath.Abs 只做词法解析、不访问文件系统，目录尚不存在
62		// （首次使用会自动创建）时也能得到稳定结果。
63		absDir, err := filepath.Abs(dir)
64		if err != nil {
65			return nil, fmt.Errorf("解析数据位置 %q 失败: %w", dir, err)
66		}
67		if err := os.MkdirAll(absDir, 0o755); err != nil {
68			return nil, fmt.Errorf("创建数据位置 %q 失败: %w", absDir, err)
69		}
70		info, err := os.Stat(absDir)
71		if err != nil {
72			return nil, fmt.Errorf("读取数据位置 %q 失败: %w", absDir, err)
73		}
74		if !info.IsDir() {
75			return nil, fmt.Errorf("数据位置 %q 不是目录", absDir)
76		}
77	
78		lockPath := filepath.Join(absDir, lockFileName)
79		lf, err := os.OpenFile(lockPath, os.O_CREATE|os.O_RDWR, 0o644)
80		if err != nil {
81			return nil, fmt.Errorf("打开锁文件失败: %w", err)
82		}
83	
84		s := &Store{dir: absDir, lockFile: lf}
85		if err := s.load(); err != nil {
86			lf.Close()
87			return nil, err
88		}
89		return s, nil
90	}
91	
92	// Close 释放台账占用的文件锁。
93	func (s *Store) Close() error {
94		s.mu.Lock()
95		defer s.mu.Unlock()
96		if s.lockFile == nil {
97			return nil
98		}
99		err := s.lockFile.Close()
100		s.lockFile = nil
101		return err
102	}
103	
104	func (s *Store) lockExclusive() error {
105		if s.lockFile == nil {
106			return errors.New("台账已关闭")
107		}
108		if err := syscall.Flock(int(s.lockFile.Fd()), syscall.LOCK_EX); err != nil {
109			return fmt.Errorf("锁定台账失败: %w", err)
110		}
111		return nil
112	}
113	
114	func (s *Store) lockShared() error {
115		if s.lockFile == nil {
116			return errors.New("台账已关闭")
117		}
118		if err := syscall.Flock(int(s.lockFile.Fd()), syscall.LOCK_SH); err != nil {
119			return fmt.Errorf("锁定台账失败: %w", err)
120		}
121		return nil
122	}
123	
124	func (s *Store) unlock() {
125		_ = syscall.Flock(int(s.lockFile.Fd()), syscall.LOCK_UN)
126	}
127	
128	func (s *Store) load() error {
129		data, err := os.ReadFile(filepath.Join(s.dir, stateFileName))
130		if err != nil {
131			if os.IsNotExist(err) {
132				s.state = &persistedState{Version: stateVersion, Requests: map[string]*requestRecord{}}
133				return nil
134			}
135			return fmt.Errorf("%w: 读取台账文件失败: %v", ErrCorruptData, err)
136		}
137		if len(data) == 0 {
138			// 区分“没有台账文件”与“已有文件但内容为空”：文件不存在才算首次使用，
139			// 零字节文件（原本就为空或使用中被截断）一律按损坏处理——既不能当成
140			// 空台账补写，也不能凭内存中的旧记录还原，调用方必须明确知道无法读取。
141			return fmt.Errorf("%w: 台账文件 %q 没有内容", ErrCorruptData, filepath.Join(s.dir, stateFileName))
142		}
143		var st persistedState
144		if err := json.Unmarshal(data, &st); err != nil {
145			return fmt.Errorf("%w: 台账文件解析失败: %v", ErrCorruptData, err)
146		}
147		if st.Version != stateVersion {
148			return fmt.Errorf("%w: 台账版本 %d 不受支持", ErrCorruptData, st.Version)
149		}
150		if err := validateState(&st); err != nil {
151			return err
152		}
153		if st.Requests == nil {
154			st.Requests = map[string]*requestRecord{}
155		}
156		s.state = &st
157		return nil
158	}
159	
160	// validateState 检查台账的引用完整性与数量合法性：
161	//   - 配方由配方编号与版本号共同识别，同一台账内每组编号+版本号只能
162	//     对应一条配方记录。只要同组出现第二条记录，无论名称、物料、每份克数
163	//     是否相同（即使内容完全一致），整份台账即视为损坏：不能挑第一条或
164	//     最后一条、不能合并物料、也不能自行删除一条后继续——重复记录会让
165	//     查询结果与批次的应投依据取决于文件中的排列顺序。重复版本即使尚未
166	//     被任何批次引用也一样拒绝，其他配方与批次完整也不能放行本次读取。
167	//   - 批次由批次编号唯一识别，同一台账内一个编号只能对应一条批次记录。
168	//     同一编号出现第二条记录，无论绑定的配方版本、计划份数、状态是否
169	//     相同（即使内容完全一致），整份台账即视为损坏：不能挑第一条或最后
170	//     一条、不能合并投料、不能自动改号或删除一条后继续——重复记录会让
171	//     同一编号查到的配方、投料与数量核对取决于文件中的排列顺序。其他
172	//     批次完整、投料数量吻合，或调用方只想查看另一个正常批次，都不能
173	//     放行本次读取；不同编号的批次绑定同一配方版本不受影响。
174	//   - 每个配方版本的每种物料，每份克数必须是正数——与登记时的规则一致。
175	//     任一版本（包括尚未被任何批次使用的版本）的任一物料为零或负数，
176	//     整份台账即视为损坏：不能改成最小用量、取绝对值、删除问题物料
177	//     或改用其他版本后继续，其他配方完整或批次数量恰好吻合也不能放行。
178	//   - 同一配方版本的物料列表内，每个物料编号只能出现一次——与登记时的
179	//     规则一致。任一版本（包括尚未被任何批次使用的版本）内同一物料编号
180	//     出现多次，整份台账即视为损坏：不能合并重复项、相加克数、丢弃其中
181	//     一条或由查询者挑一项作为依据，即使两条克数完全相同也不能放行；
182	//     不同版本、不同配方各自使用同一物料编号不受影响。
183	//   - 每个批次记录的配方编号与版本号必须共同指向一个已登记的配方版本。
184	//     任一批次找不到对应版本，整份台账即视为损坏——不能改用同编号的其他版本，
185	//     也不能按名称或物料内容替换，即使其他批次仍然完整也不能放行本次读取。
186	//   - 每个已保存批次的计划份数必须为正整数，且按该批次实际绑定的配方版本
187	//     计算，每种物料的应投量（每份克数 × 计划份数）都必须能精确表示到
188	//     千分之一克、且不超过 maxGramsMilli（9223372036854775.807 克）。
189	//     任一批次份数为零或负数，或任一物料的应投量无法精确表示/超出上限，
190	//     整份台账即视为损坏：不区分草稿、执行中还是已关闭，也不取决于本次
191	//     查询哪个批次——不能自动减少份数、改选其他配方版本或删除问题批次，
192	//     即使其他批次完整也不能放行。上限按每种物料分别判断：多种物料的
193	//     应投量相加超过上限不构成非法，单种物料恰好等于上限仍合法。
194	//   - 草稿批次不能带有任何投料记录：登记投料只允许操作执行中的批次，
195	//     草稿尚未开始执行，出现投料说明保存内容自相矛盾。任一草稿批次包含
196	//     至少一条投料，整份台账即视为损坏——即使这些投料的物料都属于绑定
197	//     版本、克数均为合法正数、累计实投恰好等于应投，也不能接受；不能
198	//     丢弃投料后当作干净草稿，不能把批次自动改为执行中或已关闭，也不
199	//     能替调用方改选配方版本来继续读取。台账里另有正常批次、调用方只
200	//     查询其他配方或批次，都不能绕过这项矛盾。没有投料的草稿不受影响；
201	//     执行中尚未投料、已关闭批次没有投料或仍有欠投超投都属正常。
202	//   - 每条已保存的投料数量必须是正数；同一批次内同一物料的累计实投
203	//     不得超过 maxGramsMilli（9223372036854775.807 克）。任一记录为零或
204	//     负数，或任一物料累计超限，整份台账即视为损坏——负数记录即使能被
205	//     正数抵消回范围内也不接受，超限也不能截断或忽略后继续。
206	//   - 每条已保存投料的物料编号必须属于该批次绑定的配方版本。归属以批次
207	//     实际绑定的版本为准：物料只出现在同编号的其他版本或其他配方中，
208	//     不能作为接受依据；也不能改选版本、补入物料或丢弃问题投料后继续。
209	func validateState(st *persistedState) error {
210		// 先按“配方编号 + 版本号”唯一标识遍历全部配方记录：同组出现第二条
211		// 记录即数据损坏，必须先于一切按标识查找的校验拒绝——否则重复记录
212		// 会让 findRecipe 总是返回排在前面的一条，查询结果与批次应投依据都
213		// 取决于文件排列顺序。完全相同的内容也不是合法重复。
214		versions := make(map[recipeKey]bool, len(st.Recipes))
215		for _, r := range st.Recipes {
216			if r == nil {
217				return fmt.Errorf("%w: 台账中存在空的配方记录", ErrCorruptData)
218			}
219			key := recipeKey{r.RecipeNo, r.Version}
220			if versions[key] {
221				return fmt.Errorf("%w: 配方编号 %q 版本号 %q 的配方记录重复",
222					ErrCorruptData, r.RecipeNo, r.Version)
223			}
224			versions[key] = true
225		}
226		for _, r := range st.Recipes {
227			seen := make(map[string]bool, len(r.Materials))
228			for _, m := range r.Materials {
229				if seen[m.MaterialNo] {
230					return fmt.Errorf("%w: 配方 %q 版本 %q 的物料编号 %q 重复",
231						ErrCorruptData, r.RecipeNo, r.Version, m.MaterialNo)
232				}
233				seen[m.MaterialNo] = true
234				if m.GramsMilli <= 0 {
235					return fmt.Errorf("%w: 配方 %q 版本 %q 物料 %q 的每份克数不是正数",
236						ErrCorruptData, r.RecipeNo, r.Version, m.MaterialNo)
237				}
238			}
239		}
240		// 再按批次编号唯一标识遍历全部批次记录：同一编号出现第二条记录即数据
241		// 损坏，必须先于一切按编号查找的校验拒绝——否则 findBatch 总是返回排在
242		// 前面的一条，同一编号查到的配方、投料与数量核对都取决于文件排列顺序。
243		// 两条记录即使绑定不同配方版本、计划份数不同或状态不同也属于重复；
244		// 内容完全一致同样不是合法记录。不能挑第一条或最后一条、不能合并投料、
245		// 也不能自动改号或删除一条后继续。不同批次绑定同一配方版本不受影响。
246		batchNos := make(map[string]bool, len(st.Batches))
247		for _, b := range st.Batches {
248			if b == nil {
249				return fmt.Errorf("%w: 台账中存在空的批次记录", ErrCorruptData)
250			}
251			if batchNos[b.BatchNo] {
252				return fmt.Errorf("%w: 批次编号 %q 的批次记录重复", ErrCorruptData, b.BatchNo)
253			}
254			batchNos[b.BatchNo] = true
255		}
256		for _, b := range st.Batches {
257			// 草稿尚未开始执行，不能登记投料；已保存的草稿却带着投料，
258			// 说明记录自相矛盾。必须先于配方归属与数量校验拒绝——否则
259			// 这份草稿还能被打开、调整份数或改选配方版本，留下按旧计划
260			// 登记的投料。不能丢弃投料当作干净草稿，不能自动改状态，也
261			// 不能改选版本后继续。
262			if b.Status == StatusDraft && len(b.Feedings) > 0 {
263				return fmt.Errorf("%w: 批次 %q 仍为草稿状态，却存在 %d 条投料记录",
264					ErrCorruptData, b.BatchNo, len(b.Feedings))
265			}
266			r := findRecipe(st, b.RecipeNo, b.RecipeVersion)
267			if r == nil {
268				return fmt.Errorf("%w: 批次 %q 绑定的配方 %q 版本 %q 未登记",
269					ErrCorruptData, b.BatchNo, b.RecipeNo, b.RecipeVersion)
270			}
271			if err := validateBatchPlan(b, r); err != nil {
272				return err
273			}
274			if err := validateFeedings(b, r); err != nil {
275				return err
276			}
277		}
278		return nil
279	}
280	
281	// validateBatchPlan 检查一个已保存批次的计划份数与按绑定配方版本算出的
282	// 应投量。份数必须为正整数；配方版本 r 的每种物料按其每份克数乘以份数
283	// 得到的应投量都必须能以千分之一克精确表示且不超过 maxGramsMilli。
284	// 归属以批次实际绑定的版本为准：换用同编号的其他版本或许能算得通，也
285	// 不能作为接受依据。上限逐种物料判断，物料之间不相加；恰好等于上限合法。
286	// 计划数量是否合法与投料无关：尚未投料、实投不足或超出应投都不影响。
287	func validateBatchPlan(b *batchRecord, r *recipeRecord) error {
288		if b.PlannedPortions <= 0 {
289			return fmt.Errorf("%w: 批次 %q 的计划份数 %d 不是正整数",
290				ErrCorruptData, b.BatchNo, b.PlannedPortions)
291		}
292		for _, m := range r.Materials {
293			if _, err := multiplyPortions(m.GramsMilli, b.PlannedPortions); err != nil {
294				return fmt.Errorf("%w: 批次 %q（计划份数 %d）物料 %q 按绑定配方 %q 版本 %q 的应投量不合法: %v",
295					ErrCorruptData, b.BatchNo, b.PlannedPortions, m.MaterialNo,
296					b.RecipeNo, b.RecipeVersion, err)
297			}
298		}
299		return nil
300	}
301	
302	// validatePlanForRecipe 校验创建或调整草稿批次时，给定份数按配方版本逐
303	// 物料计算的应投量都能精确表示到千分之一克且不超过上限。份数本身的正
304	// 整数检查由调用方按各自输入规则完成（调整草稿时份数传 0 表示不改份数，
305	// 走到这里的必是最终采用的正份数），这里只判断数量范围。
306	func validatePlanForRecipe(r *recipeRecord, portions int) error {
307		for _, m := range r.Materials {
308			if _, err := multiplyPortions(m.GramsMilli, portions); err != nil {
309				return fmt.Errorf("物料 %q 按配方 %q 版本 %q 以 %d 份计算的应投量不合法: %v",
310					m.MaterialNo, r.RecipeNo, r.Version, portions, err)
311			}
312		}
313		return nil
314	}
315	
316	// validateFeedings 检查一个批次内已保存投料的合法性与配方归属。
317	// 归属以批次绑定的配方版本 r 为准：每条投料的物料编号必须在 r 的物料
318	// 列表中，否则整份台账视为损坏。数量方面只判断数量本身是否合法，不判断
319	// 实投是否符合配方：无投料的物料累计为零属正常，不足或超过应投量也不
320	// 在此拒绝。
321	func validateFeedings(b *batchRecord, r *recipeRecord) error {
322		acc := newFeedingAccumulator()
323		for _, f := range b.Feedings {
324			belongs := false
325			for _, m := range r.Materials {
326				if m.MaterialNo == f.MaterialNo {
327					belongs = true
328					break
329				}
330			}
331			if !belongs {
332				return fmt.Errorf("%w: 批次 %q 的第 %d 条投料物料 %q 不属于其绑定的配方 %q 版本 %q",
333					ErrCorruptData, b.BatchNo, f.Seq, f.MaterialNo, b.RecipeNo, b.RecipeVersion)
334			}
335			if f.GramsMilli <= 0 {
336				return fmt.Errorf("%w: 批次 %q 物料 %q 的第 %d 条投料数量不是正数",
337					ErrCorruptData, b.BatchNo, f.MaterialNo, f.Seq)
338			}
339			if !acc.add(f.MaterialNo, f.GramsMilli) {
340				return fmt.Errorf("%w: 批次 %q 物料 %q 的累计实投超出上限 %s 克",
341					ErrCorruptData, b.BatchNo, f.MaterialNo, maxGramsMilli)
342			}
343		}
344		return nil
345	}
346	
347	// persist 先写临时文件再原子改名，并 fsync 目录，保证已提交数据可恢复。
348	func (s *Store) persist(st *persistedState) error {
349		data, err := json.MarshalIndent(st, "", "  ")
350		if err != nil {
351			return err
352		}
353		tmpPath := filepath.Join(s.dir, stateFileName+".tmp")
354		f, err := os.OpenFile(tmpPath, os.O_CREATE|os.O_WRONLY|os.O_TRUNC, 0o644)
355		if err != nil {
356			return err
357		}
358		if _, err := f.Write(data); err != nil {
359			f.Close()
360			return err
361		}
362		if err := f.Sync(); err != nil {
363			f.Close()
364			return err
365		}
366		if err := f.Close(); err != nil {
367			return err
368		}
369		if err := os.Rename(tmpPath, filepath.Join(s.dir, stateFileName)); err != nil {
370			return err
371		}
372		if d, err := os.Open(s.dir); err == nil {
373			_ = d.Sync()
374			_ = d.Close()
375		}
376		return nil
377	}
378	
379	func cloneState(st *persistedState) (*persistedState, error) {
380		data, err := json.Marshal(st)
381		if err != nil {
382			return nil, err
383		}
384		var out persistedState
385		if err := json.Unmarshal(data, &out); err != nil {
386			return nil, err
387		}
388		if out.Requests == nil {
389			out.Requests = map[string]*requestRecord{}
390		}
391		return &out, nil
392	}
393	
394	// write 是所有写入操作的统一入口：
395	//   - reqNo 为空直接报错；
396	//   - 同一 reqNo 且操作与内容完全相同，返回第一次成功的结果（幂等重放）；
397	//   - 同一 reqNo 用于其他操作或不同内容，返回 ErrRequestConflict；
398	//   - apply 在状态副本上执行，返回校验错误时不落盘、不占用请求编号；
399	//   - apply 成功后，状态与请求记录一起原子落盘，再切换到内存状态。
400	func (s *Store) write(reqNo, op string, payload any, apply func(*persistedState) (json.RawMessage, error), out any) error {
401		if reqNo == "" {
402			return errors.New("请求编号不能为空")
403		}
404		s.mu.Lock()
405		defer s.mu.Unlock()
406		if err := s.lockExclusive(); err != nil {
407			return err
408		}
409		defer s.unlock()
410	
411		// 跨进程场景下，其他进程可能已提交新数据；加锁后重新加载，
412		// 确保在最新状态上应用变更，避免用旧快照覆盖其他进程的写入。
413		if err := s.load(); err != nil {
414			return err
415		}
416	
417		payloadRaw, err := json.Marshal(payload)
418		if err != nil {
419			return err
420		}
421		payloadStr := string(payloadRaw)
422	
423		if req, ok := s.state.Requests[reqNo]; ok {
424			if req.Op != op || req.Payload != payloadStr {
425				return fmt.Errorf("%w: 请求编号 %q 已用于操作 %q，不能再用于操作 %q 或不同内容",
426					ErrRequestConflict, reqNo, req.Op, op)
427			}
428			if err := json.Unmarshal(req.Result, out); err != nil {
429				return fmt.Errorf("重放请求 %q 的结果失败: %w", reqNo, err)
430			}
431			return nil
432		}
433	
434		clone, err := cloneState(s.state)
435		if err != nil {
436			return err
437		}
438		result, err := apply(clone)
439		if err != nil {
440			return err
441		}
442		clone.Requests[reqNo] = &requestRecord{Op: op, Payload: payloadStr, Result: result}
443		if err := s.persist(clone); err != nil {
444			return fmt.Errorf("保存台账失败: %w", err)
445		}
446		s.state = clone
447		if err := json.Unmarshal(result, out); err != nil {
448			return fmt.Errorf("解析请求结果失败: %w", err)
449		}
450		return nil
451	}
452	
453	// read 在共享锁下读取当前状态。
454	func (s *Store) read(fn func(*persistedState) error) error {
455		s.mu.Lock()
456		defer s.mu.Unlock()
457		if err := s.lockShared(); err != nil {
458			return err
459		}
460		defer s.unlock()
461		if err := s.load(); err != nil {
462			return err
463		}
464		return fn(s.state)
465	}
466	
467	// 视图构造：每次都从记录全新构造，返回的切片与内部状态完全隔离。
468	
469	func buildRecipeView(r *recipeRecord) *RecipeView {
470		mats := make([]MaterialView, 0, len(r.Materials))
471		for _, m := range r.Materials {
472			mats = append(mats, MaterialView{MaterialNo: m.MaterialNo, Grams: m.GramsMilli.String()})
473		}
474		return &RecipeView{RecipeNo: r.RecipeNo, Version: r.Version, Name: r.Name, Materials: mats}
475	}
476	
477	func buildBatchView(b *batchRecord, r *recipeRecord) (*BatchView, error) {
478		v := &BatchView{
479			BatchNo:         b.BatchNo,
480			RecipeNo:        r.RecipeNo,
481			RecipeVersion:   r.Version,
482			RecipeName:      r.Name,
483			PlannedPortions: b.PlannedPortions,
484			Status:          b.Status,
485			Feedings:        make([]FeedingView, 0, len(b.Feedings)),
486			Materials:       make([]MaterialRequirement, 0, len(r.Materials)),
487		}
488	
489		for _, f := range b.Feedings {
490			v.Feedings = append(v.Feedings, FeedingView{
491				Seq:        f.Seq,
492				MaterialNo: f.MaterialNo,
493				Grams:      f.GramsMilli.String(),
494				Time:       f.Time,
495				Registrar:  f.Registrar,
496			})
497		}
498	
499		// 按物料累计实投量；台账在读取时已通过 validateFeedings 校验，
500		// 这里仍用同一套累计规则防一手整数回绕。
501		acc := newFeedingAccumulator()
502		for _, f := range b.Feedings {
503			if !acc.add(f.MaterialNo, f.GramsMilli) {
504				return nil, fmt.Errorf("%w: 批次 %q 物料 %q 的累计实投超出可表示范围",
505					ErrCorruptData, b.BatchNo, f.MaterialNo)
506			}
507		}
508	
509		// 数量核对按配方物料逐项列出；台账在读取时已通过 validateState 校验，
510		// 这里仍防一手同一版本内物料编号重复，避免返回重复的数量核对项。
511		seen := make(map[string]bool, len(r.Materials))
512		for _, m := range r.Materials {
513			if seen[m.MaterialNo] {
514				return nil, fmt.Errorf("%w: 配方 %q 版本 %q 的物料编号 %q 重复",
515					ErrCorruptData, r.RecipeNo, r.Version, m.MaterialNo)
516			}
517			seen[m.MaterialNo] = true
518			required, err := multiplyPortions(m.GramsMilli, b.PlannedPortions)
519			if err != nil {
520				return nil, fmt.Errorf("%w: 批次 %q（计划份数 %d）物料 %q 的应投量不合法: %v",
521					ErrCorruptData, b.BatchNo, b.PlannedPortions, m.MaterialNo, err)
522			}
523			act := acc.total(m.MaterialNo)
524			v.Materials = append(v.Materials, MaterialRequirement{
525				MaterialNo:      m.MaterialNo,
526				RequiredGrams:   required.String(),
527				ActualGrams:     act.String(),
528				DifferenceGrams: (act - required).String(),
529			})
530		}
531		return v, nil
532	}
533	
534	// recipeKey 是配方的唯一标识：配方编号与版本号的组合，采用精确匹配。
535	type recipeKey struct {
536		recipeNo string
537		version  string
538	}
539	
540	func findRecipe(st *persistedState, recipeNo, version string) *recipeRecord {
541		for _, r := range st.Recipes {
542			if r.RecipeNo == recipeNo && r.Version == version {
543				return r
544			}
545		}
546		return nil
547	}
548	
549	func findBatch(st *persistedState, batchNo string) *batchRecord {
550		for _, b := range st.Batches {
551			if b.BatchNo == batchNo {
552				return b
553			}
554		}
555		return nil
556	}
