274					{MaterialNo: "M1", Grams: "1"},
275				}); !errors.Is(err, ErrCorruptData) {
276					t.Fatalf("损坏台账上登记配方应返回 ErrCorruptData，得到 %v", err)
277				}
278	
279				// 被拒绝的操作不改文件、不留请求记录。
