288					bytes.Contains(after, []byte("close-rejected")) ||
289					bytes.Contains(after, []byte("R3")) {
290					t.Fatalf("被拒绝的写入不应留下请求结果或业务记录")
291				}
292	
293				// 恢复合法计划后原记录完整可用；被拒绝过的编号仍可合法提交。
294				if err := os.WriteFile(filepath.Join(dir, stateFileName), good, 0o644); err != nil {
295					t.Fatal(err)
296				}
297				b1, err := s.GetBatch("B1")
298				if err != nil {
299					t.Fatalf("恢复后查询 B1 应成功: %v", err)
300				}
301				if b1.PlannedPortions != 1 || b1.Status != StatusExecuting {
302					t.Fatalf("B1 原计划应保留: %+v", b1)
303				}
304				if b1.Materials[0].RequiredGrams != limitGrams {
305					t.Fatalf("B1 应投量应为上限，得到 %s", b1.Materials[0].RequiredGrams)
306				}
307				b2, err := s.GetBatch("B2")
308				if err != nil {
309					t.Fatalf("恢复后查询 B2 应成功: %v", err)
310				}
311				if len(b2.Feedings) != 1 || b2.Feedings[0].Grams != "5" {
312					t.Fatalf("B2 原有投料应保留: %+v", b2.Feedings)
313				}
314				if _, err := s.AddFeeding("feed-rejected", "B2", "M1", "1", time.Now(), "李四"); err != nil {
315					t.Fatalf("被拒绝过的请求编号应仍可合法使用: %v", err)
316				}
317				if c, err := s.CloseBatch("close-rejected", "B2"); err != nil || c.Status != StatusClosed {
318					t.Fatalf("被拒绝过的关闭编号应仍可合法使用: %v %+v", err, c)
319				}
320			})
321		}
322	}
323	
324	// 提交时若份数会让应投量超限，属于本次输入不合法（ErrInvalidInput），
325	// 而不是先落盘再等读取报损坏：不保存批次、不占用请求编号。
326	func TestCreateBatchPlannedRequirementOverflowIsInvalidInput(t *testing.T) {
327		s := openTestStore(t)
328		if _, err := s.RegisterRecipe("r9", "R9", "v1", "上限配方", []MaterialInput{
329			{MaterialNo: "Mbig", Grams: limitGrams},
330			{MaterialNo: "M2", Grams: "1"},
331		}); err != nil {
332			t.Fatal(err)
333		}
334		if _, err := s.CreateBatch("bad", "B1", "R9", "v1", 2); !errors.Is(err, ErrInvalidInput) {
335			t.Fatalf("创建时应投超限应返回 ErrInvalidInput，得到 %v", err)
336		}
337		if _, err := s.GetBatch("B1"); !errors.Is(err, ErrNotFound) {
338			t.Fatalf("被拒绝的创建不应留下批次，得到 %v", err)
339		}
340		// 同一请求编号修正为一份（恰好上限）后应成功。
341		b, err := s.CreateBatch("bad", "B1", "R9", "v1", 1)
342		if err != nil {
343			t.Fatalf("失败不应占用请求编号，合法份数应成功: %v", err)
344		}
345		mats := materialsMap(b)
346		checkRequirement(t, mats, "Mbig", limitGrams, "0", "-"+limitGrams)
347		checkRequirement(t, mats, "M2", "1", "0", "-1")
348	}
349	
350	// 调整草稿时最终计划应投超限必须整体拒绝（ErrInvalidInput），不留下半调整；
351	// 份数传 0 表示不改份数的语义不变——即使因此最终计划会超限，拒绝的也只是
352	// 本次提交，不能把“0 = 不改份数”当成非法份数。失败不占用请求编号。
353	func TestUpdateDraftPlannedRequirementOverflowRejected(t *testing.T) {
354		s := openTestStore(t)
355		registerTwoRecipeVersions(t, s) // R1/v1: M1=100,M2=0.5,M3=0.010；R1/v2: M1=250,M4=2
356		if _, err := s.RegisterRecipe("r9", "R9", "v1", "上限配方", []MaterialInput{
357			{MaterialNo: "Mbig", Grams: limitGrams},
358		}); err != nil {
359			t.Fatal(err)
360		}
361		if _, err := s.CreateBatch("b1", "B1", "R1", "v1", 10); err != nil {
362			t.Fatal(err)
363		}
364	
365		// 只改份数为 2：沿用 R1/v1，100×2 合法，应成功（对照组）。
366		if _, err := s.UpdateDraftBatch("u-ok", "B1", "", "", 2); err != nil {
367			t.Fatalf("合法份数调整应成功: %v", err)
368		}
369		// 改选上限配方但份数传 0：语义是“份数保持 2 不变”，Mbig×2 超限，
370		// 整体拒绝，原配方与份数保留。
371		_, err := s.UpdateDraftBatch("u-over-keep", "B1", "R9", "v1", 0)
372		if !errors.Is(err, ErrInvalidInput) {
373			t.Fatalf("份数传 0 仍表示不改份数，最终计划超限应返回 ErrInvalidInput，得到 %v", err)
374		}
375		got, err := s.GetBatch("B1")
376		if err != nil {
377			t.Fatal(err)
378		}
379		if got.RecipeNo != "R1" || got.RecipeVersion != "v1" || got.PlannedPortions != 2 {
380			t.Fatalf("失败后应保留原配方与份数，得到 %+v", got)
381		}
382		// 同一编号改成一份（恰好上限）应成功，证明份数 0 没有被当成“非法份数”
383		// 永久占用编号，失败也没占用编号。
384		v, err := s.UpdateDraftBatch("u-over-keep", "B1", "R9", "v1", 1)
385		if err != nil {
386			t.Fatalf("失败不应占用请求编号，合法调整应成功: %v", err)
387		}
388		if v.RecipeVersion != "v1" || v.PlannedPortions != 1 {
389			t.Fatalf("成功结果应指向 R9/v1 一份，得到 %+v", v)
390		}
391		checkRequirement(t, materialsMap(v), "Mbig", limitGrams, "0", "-"+limitGrams)
392	
393		// 同时改配方与份数为两份：超限，整体回滚到调整前的合法计划。
394		if _, err := s.UpdateDraftBatch("u-back-r1", "B1", "R1", "v1", 2); err != nil {
395			t.Fatalf("前置切回基础配方应成功: %v", err)
396		}
397		_, err = s.UpdateDraftBatch("u-over-combo", "B1", "R9", "v1", 2)
398		if !errors.Is(err, ErrInvalidInput) {
399			t.Fatalf("组合调整导致超限应返回 ErrInvalidInput，得到 %v", err)
400		}
401		got, _ = s.GetBatch("B1")
402		if got.RecipeNo != "R1" || got.RecipeVersion != "v1" || got.PlannedPortions != 2 {
403			t.Fatalf("组合调整失败应整体回滚，得到 %+v", got)
404		}
405	
406		// 份数传 0 的无变化调整依旧合法（明确不能把已保存数据检查变成
407		// 对合法调用的拒绝）；改选版本但保持当前份数不变也同理。
408		if _, err := s.UpdateDraftBatch("u-nop", "B1", "", "", 0); err != nil {
409			t.Fatalf("份数传 0 的无变化调整应继续合法: %v", err)
410		}
411		if _, err := s.UpdateDraftBatch("u-keep-two", "B1", "R9", "v1", 0); !errors.Is(err, ErrInvalidInput) {
412			t.Fatalf("保持 2 份切到上限配方仍应因最终计划超限返回 ErrInvalidInput，得到 %v", err)
413		}
414		got, _ = s.GetBatch("B1")
415		if got.RecipeNo != "R1" || got.PlannedPortions != 2 {
416			t.Fatalf("两次拒绝都不应改动批次，得到 %+v", got)
417		}
418	}
419	
420	// 计划合法但尚未投料、实投不足或超出应投都不影响读取；
421	// 执行中批次仍可按原规则关闭，关闭后重开仍可查询，不新增数量吻合要求。
422	func TestLegalPlanWithAnyFeedingStateStillUsable(t *testing.T) {
423		dir := t.TempDir()
424		s, err := Open(dir)
425		if err != nil {
426			t.Fatal(err)
427		}
428		if _, err := s.RegisterRecipe("r9", "R9", "v1", "上限配方", []MaterialInput{
429			{MaterialNo: "Mbig", Grams: limitGrams},
430			{MaterialNo: "M2", Grams: "1"},
431		}); err != nil {
432			t.Fatal(err)
433		}
434		// 一份上限配方：未投料的草稿即可查询。
435		if _, err := s.CreateBatch("bd", "B-draft", "R9", "v1", 1); err != nil {
436			t.Fatal(err)
437		}
438		dv, err := s.GetBatch("B-draft")
439		if err != nil {
440			t.Fatal(err)
441		}
442		dm := materialsMap(dv)
443		checkRequirement(t, dm, "Mbig", limitGrams, "0", "-"+limitGrams)
444	
445		if _, err := s.CreateBatch("b1", "B1", "R9", "v1", 1); err != nil {
446			t.Fatal(err)
447		}
448		if _, err := s.StartBatch("s1", "B1"); err != nil {
449			t.Fatal(err)
450		}
451		// 实投远低于应投（欠投），随后关闭——不要求数量吻合。
452		if _, err := s.AddFeeding("f1", "B1", "M2", "1", time.Now(), "张三"); err != nil {
453			t.Fatal(err)
454		}
455		under, err := s.GetBatch("B1")
456		if err != nil {
457			t.Fatal(err)
458		}
459		um := materialsMap(under)
460		checkRequirement(t, um, "Mbig", limitGrams, "0", "-"+limitGrams)
461		checkRequirement(t, um, "M2", "1", "1", "0")
462		c, err := s.CloseBatch("c1", "B1")
463		if err != nil {
464			t.Fatalf("欠投也应允许按原规则关闭: %v", err)
465		}
466		if c.Status != StatusClosed {
467			t.Fatalf("关闭后状态应为已关闭，得到 %s", c.Status)
468		}
469	
470		// 超投场景：另一执行中批次，M2 应投 1 克，投 2 克，仍可查询与关闭。
471		if _, err := s.CreateBatch("b2", "B2", "R9", "v1", 1); err != nil {
472			t.Fatal(err)
473		}
474		if _, err := s.StartBatch("s2", "B2"); err != nil {
475			t.Fatal(err)
476		}
477		if _, err := s.AddFeeding("f2", "B2", "M2", "2", time.Now(), "李四"); err != nil {
478			t.Fatal(err)
479		}
480		over, err := s.GetBatch("B2")
481		if err != nil {
482			t.Fatal(err)
483		}
484		om := materialsMap(over)
485		checkRequirement(t, om, "M2", "1", "2", "1")
486		if _, err := s.CloseBatch("c2", "B2"); err != nil {
487			t.Fatalf("超投也应允许关闭: %v", err)
488		}
489	
490		// 关闭后重新打开：全部批次仍可查询，状态与数量核对不变。
491		if err := s.Close(); err != nil {
492			t.Fatal(err)
493		}
494		s2, err := Open(dir)
495		if err != nil {
496			t.Fatalf("含上限应投、欠投/超投/未投料批次的台账应能重新打开: %v", err)
497		}
498		defer s2.Close()
499		for _, want := range []struct {
500			no     string
501			status BatchStatus
502		}{
503			{"B-draft", StatusDraft}, {"B1", StatusClosed}, {"B2", StatusClosed},
504		} {
505			b, err := s2.GetBatch(want.no)
506			if err != nil {
507				t.Fatalf("重开后查询批次 %q 失败: %v", want.no, err)
508			}
509			if b.Status != want.status {
510				t.Fatalf("批次 %q 状态应保留为 %s，得到 %s", want.no, want.status, b.Status)
511			}
512		}
513	}
